"use client";

import { type HTMLAttributes, type MouseEvent, type PointerEvent, useRef } from "react";
import { cx } from "../utils/cx";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  useMenu,
} from "./dropdown-menu";

/** A right-click (or long-press, or the keyboard's menu key) menu: the DropdownMenu, placed at the pointer. */
export function ContextMenu({ children, ...rest }: Omit<Parameters<typeof DropdownMenu>[0], "side" | "align">) {
  return (
    <DropdownMenu {...rest} side="right" align="start">
      {children}
    </DropdownMenu>
  );
}

/**
 * The area that owns the menu. It is focusable so the menu key and Shift+F10 work from the keyboard, and focus returns
 * to it when the menu closes. On touch, holding for half a second opens the menu (iOS sends no contextmenu event).
 */
export function ContextMenuTrigger({
  className,
  onContextMenu,
  onPointerDown,
  onPointerUp,
  onPointerCancel,
  onPointerMove,
  ...rest
}: HTMLAttributes<HTMLDivElement>) {
  const { setOpen, triggerRef } = useMenu("ContextMenuTrigger");
  const region = useRef<HTMLDivElement>(null);
  const hold = useRef<ReturnType<typeof setTimeout>>(undefined);

  const openAt = (x: number, y: number) => {
    // a one-pixel virtual anchor at the pointer; focus goes back to the region, not the anchor
    const anchor = document.createElement("span");
    anchor.getBoundingClientRect = () => new DOMRect(x, y, 0, 0);
    anchor.focus = () => region.current?.focus();
    (triggerRef as { current: HTMLElement | null }).current = anchor;
    setOpen(true);
  };
  const cancelHold = () => clearTimeout(hold.current);
  return (
    <div
      {...rest}
      ref={region}
      tabIndex={rest.tabIndex ?? 0}
      className={cx("hm-context-area", className)}
      onContextMenu={(e: MouseEvent<HTMLDivElement>) => {
        onContextMenu?.(e);
        if (e.defaultPrevented) return;
        e.preventDefault();
        const r = e.currentTarget.getBoundingClientRect();
        // the keyboard's menu key reports (0, 0): anchor to the region instead
        openAt(e.clientX || r.left + 16, e.clientY || r.top + 16);
      }}
      onPointerDown={(e: PointerEvent<HTMLDivElement>) => {
        onPointerDown?.(e);
        if (e.pointerType !== "touch") return;
        const { clientX, clientY } = e;
        hold.current = setTimeout(() => openAt(clientX, clientY), 500);
      }}
      onPointerUp={(e) => {
        onPointerUp?.(e);
        cancelHold();
      }}
      onPointerCancel={(e) => {
        onPointerCancel?.(e);
        cancelHold();
      }}
      onPointerMove={(e) => {
        onPointerMove?.(e);
        if (e.pointerType === "touch") cancelHold();
      }}
    />
  );
}

export const ContextMenuContent = DropdownMenuContent;
export const ContextMenuItem = DropdownMenuItem;
export const ContextMenuLabel = DropdownMenuLabel;
export const ContextMenuSeparator = DropdownMenuSeparator;
